Lemma map_upd : forall {X Y} (f : X -> Y) (l : list X) k x, map f (upd l k x) = upd (map f l) k (f x).
Proof. intros X Y f l. induction l as [|y l IH]; intros [|k] x; cbn; try reflexivity. rewrite IH. reflexivity. Qed.

Lemma ft_map_upto_step : forall n, (1 <= n)%nat ->
  upd (map b8 (ft_map_upto (n - 1))) (Z.to_nat (ft_slot n)) (b8 (Z.of_nat n)) = map b8 (ft_map_upto n).
Proof.
  intros [|n'] H; [lia|]. cbn [ft_map_upto]. replace (S n' - 1)%nat with n' by lia. rewrite map_upd. reflexivity.
Qed.

Lemma ft_map_upto_0_bytes : map b8 (ft_map_upto 0) = repeat (Z_to_bv 8 0) 1367.
Proof. cbn [ft_map_upto]. apply map_repeat. Qed.

Definition AFTC_STACK : Z := 96 + AINTRIN_STACK.     (* [comment removed for export] *)
Definition ftc_W (lo : Z) (sp : word) : list (Z * Z) := [(lo, bv_unsigned sp); (AG_FIELD_TABLE, AG_FIELD_TABLE + 3448)]%Z.

(* [comment removed for export] *)
Lemma ftc_W_awin : forall lo sp, aceil <= lo -> Forall awin (ftc_W lo sp).
Proof.
  intros lo sp CEIL. unfold ftc_W.
  apply Forall_cons; [apply awin_stack; exact CEIL|]. apply Forall_cons; [| apply Forall_nil].
  apply ft_tab_awin; lia.
Qed.

Definition ftc_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7
                  s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom bsegs)
    /\ munch (ftc_W lo sp) m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp)
    /\ rw_cells bsegs m' AG_FIELD_TABLE FTCells /\ FTInit m'
    /\ ACONST m'.

Definition ftc_stmt : Prop :=
  forall ra sp gp tp t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (lo : Z) (j1 j2 : list byte),
  rw_cells bsegs m AG_FIELD_TABLE [CB 2080 j1; CB 1367 j2; CB 1 (zeros 1)] -> FTInit m ->
  stk bsegs m lo (bv_unsigned sp) -> lo + AFTC_STACK <= bv_unsigned sp -> aceil <= lo ->
  mem_inv bsegs m ->
  (* [comment removed for export] *)
  ACONST m ->
  evt bsegs (ftc_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz AG_FIELD_TABLE) a1 a2 a3 a4 a5 a6 a7
              s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_FIELD_TABLE_CTOR) fc None m (seg_rom bsegs)).

(* [comment removed for export] *)
(* [comment removed for export] *)

(* [comment removed for export] *)
Definition ftc_ctx (m0 m : mem) (sp : word) (lo : Z) (rav s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v : word) (j8 : list byte) (k : nat) : Prop :=
  rw_cells bsegs m (bv_unsigned sp + -96) [CB 8 j8; C8 s9v; C8 s8v; C8 s7v; C8 s6v; C8 s5v; C8 s4v; C8 s3v; C8 s2v; C8 s1v; C8 s0v; C8 rav]
  /\ rw_cells bsegs m 6684432 [CB 2080 FT_TAB_BYTES]
  /\ u8arr bsegs m 6686512 (map b8 (ft_map_upto k))
  /\ rw_cells bsegs m 6687879 [CB 1 (zeros 1)]
  /\ bytes_at bsegs m 1157696 FT_TAB_BYTES
  /\ stk bsegs m lo (bv_unsigned sp + -96)
  /\ munch [(lo, bv_unsigned sp); (6684432, 6684432 + 3448)]%Z m0 m /\ wmono bsegs m0 m /\ mem_inv bsegs m
  /\ ACONST m0.

Lemma ftc_aconst_now : forall m0 m lo hi,
  ACONST m0 -> munch [(lo, hi); (6684432, 6684432 + 3448)]%Z m0 m -> wmono bsegs m0 m -> aceil <= lo -> ACONST m.
Proof.
  intros m0 m lo hi AC MU WM CEIL. eapply aconst_transport_awin; [exact AC | exact MU | exact WM |].
  apply Forall_cons; [apply awin_stack; exact CEIL|]. apply Forall_cons; [| apply Forall_nil].
  apply ft_tab_awin; unfold AG_FIELD_TABLE; lia.
Qed.
