Lemma ftc_loop : forall kk (i : nat) rax sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m0 m : mem) (lo : Z) (rav s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v : word) (j8 : list byte),
  (130 - i = kk)%nat -> (1 <= i <= 129)%nat ->
  ftc_ctx m0 m sp lo rav s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v j8 (i - 1) -> lo + AFTC_STACK <= bv_unsigned sp -> aceil <= lo ->
  evt bsegs (fun ms' => exists t0' t1' t2' a0' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' m',
    ms' = MS (mkR rav sp gp tp t0' t1' t2' s0v s1v a0' a1' a2' a3' a4' a5' a6' a7'
                  s2v s3v s4v s5v s6v s7v s8v s9v s10 s11 t3' t4' t5' t6')
             F (ret_pc rav) fc None m' (seg_rom bsegs)
    /\ munch [(lo, bv_unsigned sp); (6684432, 6684432 + 3448)]%Z m0 m' /\ wmono bsegs m0 m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp)
    /\ rw_cells bsegs m' 6684432 FTCells /\ FTInit m'
    /\ ACONST m')
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -96)) gp tp t0 t1 t2 (wz 6686512) (wz (6684432 + 16 * Z.of_nat i)) a0 a1 a2 a3 a4 a5 a6 a7
              (wz (6684432 + 16 * Z.of_nat i + 8)) (wz ASHADOW_BASE) (wz 1367) (wz 18446744073702865103) (wz (Z.of_nat i))
              (wz (2148286434 + 2 * Z.of_nat i)) (wz 9189636224090898432) (wz 130) s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 0xbf2b0) fc None m (seg_rom bsegs)).
