Lemma ft_guard_accessible : forall m, ACONST m -> accessible m AG_FIELD_TABLE_GUARD 8.
Proof.
  intros m AC. eapply accessible_sub; [exact (ft_tab_accessible m AC) | | |]; unfold AG_FIELD_TABLE, AG_FIELD_TABLE_GUARD; lia.
Qed.

